18	+//! The checker's answers kept for one snapshot, each asked once however many conversions want it, at once or later.
19	+//!
20	+//! The lanes of a run answer several components at a time over one converter ([`crate::convert::Converter`]), and
21	+//! components of one library walk the same types in the same order: without this, two of them asked every question
22	+//! twice, each missing a memo the other had not filled yet (Chakra: 520k of 732k `isReadonlySymbol` requests, 5,400 of
23	+//! 8,900 `typeToString`). An answer is a function of the snapshot and the question alone, so which conversion asks it
24	+//! first cannot show in the output.
25	+
26	+use std::future::Future;
27	+use std::hash::Hash;
28	+use std::sync::{Arc, Mutex, PoisonError};
29	+
30	+use rustc_hash::FxHashMap;
31	+use tokio::sync::OnceCell;
32	+
33	+use crate::rpc::CallError;
34	+
35	+/// Answers by question. A question asked while another conversion waits for its answer waits for that answer instead
36	+/// of asking again. An answer that failed is not kept: the next to ask asks again, as it would have without this.
37	+pub(crate) struct Answers<K, V> {
38	+    cells: Mutex<FxHashMap<K, Arc<OnceCell<V>>>>,
39	+}
40	+
41	+impl<K, V> Default for Answers<K, V> {
42	+    fn default() -> Self {
43	+        Answers { cells: Mutex::default() }
44	+    }
45	+}
46	+
47	+impl<K: Eq + Hash, V: Clone> Answers<K, V> {
48	+    /// The answer to `key`, from `ask` when it was not asked before.
49	+    pub(crate) async fn get<F, Fut>(&self, key: K, ask: F) -> Result<V, CallError>
50	+    where
51	+        F: FnOnce() -> Fut,
52	+        Fut: Future<Output = Result<V, CallError>>,
53	+    {
54	+        let cell = self.cells.lock().unwrap_or_else(PoisonError::into_inner).entry(key).or_default().clone();
55	+        cell.get_or_try_init(ask).await.cloned()
56	+    }
57	+}
58	+
