61	+    #![allow(clippy::unwrap_used)]
62	+
63	+    use std::sync::atomic::{AtomicU32, Ordering};
64	+
65	+    use super::*;
66	+
67	+    fn run<T>(work: impl Future<Output = T>) -> T {
68	+        tokio::runtime::Builder::new_current_thread().build().unwrap().block_on(work)
69	+    }
70	+
71	+    #[test]
72	+    fn a_question_is_asked_once_and_a_failure_is_asked_again() {
73	+        run(async {
74	+            let answers: Answers<u64, u32> = Answers::default();
75	+            let asked = AtomicU32::new(0);
76	+            let ask = |value: u32| {
77	+                let asked = &asked;
78	+                move || async move {
79	+                    asked.fetch_add(1, Ordering::Relaxed);
80	+                    Ok(value)
81	+                }
82	+            };
83	+            assert_eq!(answers.get(1, ask(10)).await.unwrap(), 10);
84	+            assert_eq!(answers.get(1, ask(20)).await.unwrap(), 10);
85	+            assert_eq!(answers.get(2, ask(30)).await.unwrap(), 30);
86	+            assert_eq!(asked.load(Ordering::Relaxed), 2);
87	+
88	+            let failed = answers.get(3, || async { Err(CallError::Rejected("no".to_string())) }).await;
89	+            assert!(matches!(failed, Err(CallError::Rejected(message)) if message == "no"));
90	+            assert_eq!(answers.get(3, ask(40)).await.unwrap(), 40);
91	+            assert_eq!(asked.load(Ordering::Relaxed), 3);
92	+        });
93	+    }
94	+
95	+    #[test]
96	+    fn a_question_asked_while_it_is_being_answered_waits_for_that_answer() {
97	+        run(async {
98	+            let answers: Arc<Answers<u64, u32>> = Arc::default();
99	+            let asked = Arc::new(AtomicU32::new(0));
100	+            let (release, wait) = tokio::sync::oneshot::channel::<()>();
101	+            let first = tokio::spawn({
102	+                let (answers, asked) = (answers.clone(), asked.clone());
103	+                async move {
104	+                    answers
105	+                        .get(1, || async move {
106	+                            asked.fetch_add(1, Ordering::Relaxed);
107	+                            wait.await.ok();
108	+                            Ok(1)
109	+                        })
110	+                        .await
111	+                }
112	+            });
113	+            // The first is now waiting on its answer.
114	+            tokio::task::yield_now().await;
115	+            let second = tokio::spawn({
116	+                let (answers, asked) = (answers.clone(), asked.clone());
117	+                async move {
118	+                    answers
119	+                        .get(1, || async move {
120	+                            asked.fetch_add(1, Ordering::Relaxed);
121	+                            Ok(2)
122	+                        })
123	+                        .await
124	+                }
125	+            });
126	+            tokio::task::yield_now().await;
127	+            release.send(()).unwrap();
128	+            assert_eq!((first.await.unwrap().unwrap(), second.await.unwrap().unwrap()), (1, 1));
129	+            assert_eq!(asked.load(Ordering::Relaxed), 1);
130	+        });
131	+    }
132	+}
